import{registerRootRoom,feedLift,bossLift}from'./matriarch-arena.js';
import{eggShellMesh,paintEggShell,eggStemMesh,eggCountdown}from'./matriarch-egg.js';
import{creatureBuilder}from'./dungeon-creature-mesh.js';import{rootActive,rootBoss,VINE_RULES,vineEscapePath}from'./matriarch-mechanic.js';import{walkable}from'./core.js';import{tubeMesh,paintRootMesh,elasticPose,WOOD}from'./matriarch-root-geometry.js';
export{summonBushMesh,paintSummonBush}from'./matriarch-bush.js';
const clamp=x=>Math.max(0,Math.min(1,x)),project=(x,y,z=0)=>({x:50+22*x+2*y,y:57.5+16*y-z}),arcCache=new WeakMap(),hints=new WeakMap();
export const rootRadius=t=>.6+8.4*Math.pow(1-clamp(t),1.15);
export function sapArcPoint(f,t){const dx=f.x-f.start.x,dy=f.y-f.start.y,d=Math.hypot(dx,dy)||1,u=.14+.86*t;return{x:f.start.x+dx*u-dy/d*Math.sin(t*Math.PI*2)*.18,y:f.start.y+dy*u+dx/d*Math.sin(t*Math.PI*2)*.18,z:Math.sin(t*Math.PI*6)*19+feedLift(f)*Math.max(0,1-t*6)};}
export function sapArcs(f,beat){const grow=Math.floor(clamp((beat-f.born)/VINE_RULES.growBeats)*96)/96;let cache=arcCache.get(f);if(!cache){cache=new Map();arcCache.set(f,cache);}if(cache.has(grow))return cache.get(grow);const out=[];for(let arch=0;arch<3;arch++){const start=arch/3,end=Math.min(start+1/6,grow);if(end<=start)continue;const points=Array.from({length:9},(_,i)=>sapArcPoint(f,start+(end-start)*i/8)),mid=points[4],faces=tubeMesh('sap-root',points.map(p=>[p.x*22,p.y*22,p.z]),t=>rootRadius(start+(end-start)*t));out.push({type:'sapArc',hp:1,id:f.id*10-arch,x:Math.round(mid.x),y:Math.round(mid.y),visualDepth:mid.y,a:points[0],b:points.at(-1),points,faces,feed:f,t:start,arch});}if(cache.size>=12)cache.delete(cache.keys().next().value);cache.set(grow,out);return out;}
export function rootSceneEntities(room,beat){return room.enemies.filter(b=>rootActive(b)&&b.hp>0).flatMap(b=>{const f=b.vine.feed;if(f)registerRootRoom(f,room,b);return[...(f&&(f.hp>0||f.hatchAt!==undefined&&beat-f.hatchAt<.85)?[...(f.hp>0?sapArcs(f,beat):[]),...(beat>=f.activeAt?[{type:'sapPresentation',id:f.id,x:f.x,y:f.y,hp:1,feed:f}]:[])]:[]),...b.vine.bushes.map(p=>({...p,type:'summonBush',hp:1}))];});}
export function rootContact(f,arch,beat){const at=f.born+VINE_RULES.growBeats*(arch/3+1/6),age=beat-at,p=sapArcPoint(f,arch/3+1/6);return{age,p,active:age>=0&&age<.8};}
export function paintSapArc(c,n,beat){c.save();c.globalAlpha=.15;c.strokeStyle='#161928';c.lineWidth=5;c.lineCap='round';c.beginPath();n.points.forEach((p,i)=>{const q=project(p.x,p.y);i?c.lineTo(q.x,q.y):c.moveTo(q.x,q.y);});c.stroke();c.restore();paintRootMesh(c,n.faces);const flow=((beat-n.feed.born)*.14)%1;if(flow>=n.t&&flow<=n.t+1/6){const p=sapArcPoint(n.feed,flow),s=project(p.x,p.y,p.z);c.save();c.fillStyle='#f7bf6f';c.beginPath();c.arc(s.x-1,s.y-1,1.1,0,Math.PI*2);c.fill();c.restore();}const contact=rootContact(n.feed,n.arch,beat);if(contact.active){const {age,p}=contact,u=age/.8,q=project(p.x,p.y);c.save();c.globalAlpha=(1-u)*.7;c.strokeStyle='#ed9353';c.lineWidth=1;c.beginPath();c.ellipse(q.x,q.y,4+u*14,2+u*7,0,0,Math.PI*2);c.stroke();for(let i=0;i<5;i++){const a=i*Math.PI*2/5,pt=project(p.x+Math.cos(a)*u*.6,p.y+Math.sin(a)*u*.6,Math.sin(u*Math.PI)*7);c.fillStyle=i%2?'#9c3824':'#ed9353';c.fillRect(pt.x-1.3,pt.y-1.3,2.6,2.6);}c.restore();}}
export function eggPose(f,beat,soft=false){const q=clamp((f.charge||0)/VINE_RULES.chargeBeats),phase=beat-Math.floor(beat),pulse=Math.max(0,1-phase/.33),danger=q*q*q,hop=Math.sin(phase*Math.PI)*danger*(soft?1:5),shake=Math.sin(beat*Math.PI*4)*danger*(soft?.02:.12),age=f.hatchAt===undefined?0:clamp((beat-f.hatchAt)/.85);return{q,scale:1+q*.16+pulse*q*.035,hop,shake,age,hatched:f.state==='hatched'};}
export function eggShellShards(f,beat){const m=creatureBuilder({soft:true}),u=eggPose(f,beat).age,ramp=['#a2e66f','#5dae27','#1d3926'];for(let i=0;i<6;i++){const a=i*Math.PI/3,x=Math.cos(a)*(5+u*19),y=Math.sin(a)*(4+u*12),z=Math.max(.5,5+Math.sin(u*Math.PI)*13-u*6),co=Math.cos(a+u*3),si=Math.sin(a+u*3),tf=p=>[x+p[0]*co-p[1]*si,y+p[0]*si+p[1]*co,z+p[2]],bottom=[[-3,-2,0],[3,-1,0],[0,3,0]],top=bottom.map(([x,y,z])=>[x,y,z+1.2]);m.face('egg-shard',top,ramp,tf);for(let j=0;j<3;j++){const k=(j+1)%3;m.face('egg-shard',[bottom[j],bottom[k],top[k],top[j]],ramp,tf);}}return m.finish();}
export function sapRootMesh(f,beat,soft=false){return f.state==='hatched'?eggShellShards(f,beat):eggShellMesh(f,eggPose(f,beat,soft));}
export function paintSapRoot(c,f,x,y,beat,soft=false,timeAt=undefined){const pose=eggPose(f,beat,soft),mesh=sapRootMesh(f,beat,soft);paintRootMesh(c,eggStemMesh(f,pose),x,y);if(f.state==='hatched'){c.save();c.globalAlpha=1-pose.age;paintRootMesh(c,mesh,x,y);c.restore();return;}paintEggShell(c,mesh,x,y,pose);const timer=eggCountdown(f,beat,timeAt);c.save();c.font='bold 7px Arial';c.textAlign='center';c.lineWidth=2;c.strokeStyle='#161928';c.fillStyle='#ffd95a';const yy=y-4-34*pose.scale-pose.hop-14;c.strokeText(timer.label,x,yy);c.fillText(timer.label,x,yy);c.fillStyle='#161928';c.fillRect(x-17,yy+4,34,4);c.fillStyle='#a2e66f';c.fillRect(x-16,yy+5,32*timer.fraction,2);c.restore();}

function hint(r,b){const key=r.beat+':'+r.player.x+','+r.player.y,old=hints.get(b);if(old?.key===key)return old.p;const path=vineEscapePath(r.room,b,r.player,walkable),p=path?.at(-1)||r.player;hints.set(b,{key,p});return p;}
export function paintVineGround(c,b,r,beat,worldProject,soft=false,renderedPlayer=null){const m=b.vine,g=m.grab;if(g){const target=g.stage==='bound'?r.player:g.target,visual=g.stage==='bound'&&renderedPlayer?{x:(renderedPlayer.x-100-(renderedPlayer.y-115)/8)/44,y:(renderedPlayer.y-115)/32}:target,amount=g.stage==='warn'?clamp((beat-g.started)/2):1,end=[(b.x+(visual.x-b.x)*amount)*22,(b.y+(visual.y-b.y)*amount)*22,g.stage==='bound'?12:1],radial=Math.hypot(visual.x-b.x,visual.y-b.y),tension=g.stage==='bound'?clamp((radial-g.origin)/VINE_RULES.escapeGain):0,pose=elasticPose([b.x*22,b.y*22,6+bossLift(b,r.room)],end,tension,beat,soft);paintRootMesh(c,tubeMesh('elastic-vine',pose.points,pose.radius));}if(m.breakPoint&&beat>=m.breakAt&&beat<m.breakAt+.85){const age=(beat-m.breakAt)/.85,start=[b.x*22,b.y*22,6+bossLift(b,r.room)],end=renderedPlayer?[(renderedPlayer.x-100-(renderedPlayer.y-115)/8)/2,(renderedPlayer.y-115)*22/32,12]:[m.breakPoint.x*22,m.breakPoint.y*22,12],middle=start.map((n,i)=>(n+end[i])/2),spring=1-Math.exp(-age*7)*Math.cos(age*12),left=start.map((n,i)=>n+(middle[i]-n)*(1-spring*.8)),right=end.map((n,i)=>n+(middle[i]-n)*(1-spring*.8));c.save();c.globalAlpha=1-age;for(const[a,z]of[[start,left],[right,end]]){const p=elasticPose(a,z,.6,beat,soft);paintRootMesh(c,tubeMesh('snap-recoil',p.points,p.radius));}c.restore();}}
export function paintVineWrap(c,r,position,beat,layer){const b=rootBoss(r.room),g=b?.vine.grab;if(g?.stage!=='bound')return;const x=position.x/2,y=position.y/2-12,q=clamp(g.progress/VINE_RULES.escapeGain);c.save();c.lineCap='round';c.strokeStyle=layer==='behind'?'#591d35':'#9c3824';c.lineWidth=4/(1+q*.3);c.beginPath();c.ellipse(x,y,11-q,4,0,layer==='behind'?Math.PI:0,layer==='behind'?Math.PI*2:Math.PI);c.stroke();if(layer==='front'){c.strokeStyle='#ed9353';c.lineWidth=1.2;c.stroke();const h=hint(r,b),dx=h.x-r.player.x,dy=h.y-r.player.y,sx=dx*22+dy*2,sy=dy*16,len=Math.hypot(sx,sy)||1,ax=sx/len,ay=sy/len,start={x:x+ax*16,y:position.y/2+ay*10};c.strokeStyle='#ffd95a';c.lineWidth=2;c.beginPath();c.moveTo(start.x,start.y);c.lineTo(start.x+ax*22,start.y+ay*22);c.moveTo(start.x+ax*22-ax*6-ay*4,start.y+ay*22-ay*6+ax*4);c.lineTo(start.x+ax*22,start.y+ay*22);c.lineTo(start.x+ax*22-ax*6+ay*4,start.y+ay*22-ay*6-ax*4);c.stroke();c.font='bold 8px Arial';c.textAlign='center';c.strokeStyle='#161928';c.lineWidth=2;c.fillStyle='#ffd95a';c.strokeText('ESTIQUE!',x,y-34);c.fillText('ESTIQUE!',x,y-34);c.fillStyle='#591d35';c.fillRect(x-12,y-29,24,3);c.fillStyle='#ed9353';c.fillRect(x-12,y-29,24*q,3);}c.restore();}
